198	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
199	        if (email == null || email.trim().isEmpty()) {
200	            throw new Xxd47Exception("사용자 이메일이 없습니다.");
201	        }
202	        if (productSizeId == null) {
203	            throw new Xrf10Exception("상품 사이즈 ID가 없습니다.");
204	        }
205	        if (bidPrice <= 0) {
206	            throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
207	        }
208	    }
