67 switch (requestDto.getResolvedPaymentType()) {
68 case "CARD":
69 payment = createCardPayment(order, user, (Xqg94RequestDto) requestDto);
70 break;
71 case "ACCOUNT":
72 payment = createAccountPayment(order, user, (Xkg34RequestDto) requestDto);
